-- rowstile 0.1.0-dev: identity_ids_and_signature. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '1f49f27711ac7a48', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '1f49f27711ac7a48' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '1f49f27711ac7a48' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '1f49f27711ac7a48' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '9839104aa26bc1df' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '9839104aa26bc1df', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP FUNCTION IF EXISTS
  authz_int."app.notes:seen"(p_id integer),
  authz_int."file__folder__why"(p_id integer, p_depth int, p_seen text[], p_asker text[]),
  authz_int."folder__parent__why"(p_id integer, p_depth int, p_seen text[], p_asker text[]),
  authz_int."note__file__why"(p_id integer, p_depth int, p_seen text[], p_asker text[]);

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- HMAC-SHA256 of who is signed in, this backend and this transaction
CREATE OR REPLACE FUNCTION authz_int.session_sig() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.to_jsonb(ARRAY[coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text])::text, 'UTF8'))), 'hex');
END $f$;

-- Are the settings to be believed? PL/pgSQL, so its plans are kept for the session, and not a definer: all its
-- callers run as the owner. (OR runs left to right: the refusal is asked only when the signature doesn't match.)
-- The two signatures are compared through their hashes: the time it takes says nothing of how many characters of
-- the one given are right.
CREATE OR REPLACE FUNCTION authz_int.session_ok() RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.sha256(pg_catalog.convert_to(coalesce(current_setting('authz.session', true), ''), 'UTF8'))
         = pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.to_jsonb(ARRAY[coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text])::text, 'UTF8'))), 'hex'), 'UTF8'))
         OR authz_int.session_refused();
END $f$;

-- A transaction is one principal's: act_as and the logins refuse to sign in someone else (nobody included) once
-- someone is signed in, and to sign in again at all once the transaction views as someone or is limited by scopes
-- (that would end what limits it). Signing in from nobody to someone, and as the same principal again, are fine.
-- Only a sign-in made in this transaction counts (its signature): the policy's owner and superusers say who is
-- signed in by hand, and aren't held to it. rowstile's own functions that ask as others and put back the caller
-- (who, explain, who_among, the invariants) switch without it.
CREATE OR REPLACE FUNCTION authz_int.one_principal(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key; v_id text := coalesce(current_setting('authz.user_id', true), '');
        v_type text := coalesce(current_setting('authz.principal_type', true), '');
BEGIN
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN;
  END IF;
  SELECT * INTO k FROM authz_int.session_key;
  -- (compared through their hashes, as session_ok() does)
  IF pg_catalog.sha256(pg_catalog.convert_to(coalesce(current_setting('authz.session', true), ''), 'UTF8'))
     <> pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.to_jsonb(ARRAY[coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text])::text, 'UTF8'))), 'hex'), 'UTF8')) THEN
    RETURN;  -- nobody signed in in this transaction yet
  END IF;
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'this transaction views as user %, so it can''t sign in again', v_id
      USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
  IF v_id <> '' AND (v_id, v_type) IS DISTINCT FROM (coalesce(p_id, ''), coalesce(p_type, '')) THEN
    RAISE EXCEPTION 'this transaction is signed in as % already, so it can''t sign in as %',
      CASE WHEN v_type = '' THEN 'user ' || v_id ELSE v_type || ' ' || v_id END,
      CASE WHEN coalesce(p_id, '') = '' THEN 'nobody' WHEN coalesce(p_type, '') = '' THEN 'user ' || p_id
           ELSE p_type || ' ' || p_id END
      USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
  IF coalesce(current_setting('authz.scopes', true), '') <> '' THEN
    RAISE EXCEPTION 'this transaction is limited by scopes (%), so it can''t sign in again',
      current_setting('authz.scopes', true) USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
END $f$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_integer integer;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), '');
        v_asker text[];   -- for another user: the one asking, whose sight the walk keeps to
BEGIN
  -- the signed-in user's own id is the signed-in user: asked as without it (a service whose id is a user's is not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS NOT DISTINCT FROM authz.uid()::text THEN
    p_user := NULL;
  END IF;
  -- another user's access: only for people who may inspect the object, within their scopes (as authz.who)
  IF p_user IS NOT NULL AND (NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm)) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  IF p_user IS NOT NULL THEN
    v_asker := ARRAY[v_me, v_pt, v_scopes];
    PERFORM set_config('authz.user_id', authz_int.canon('user', p_user), true);
    PERFORM set_config('authz.principal_type', '', true);
    PERFORM set_config('authz.scopes', '', true);   -- that user's access, with full rights (as authz.who)
    PERFORM authz_int.sign();
  END IF;
  v_ok := authz.can(p_type, p_id, p_perm);
  RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
    || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(v_integer, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."folder__view__why"(v_integer, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."file__edit__why"(v_integer, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."file__view__why"(v_integer, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."note__edit__why"(v_integer, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."note__view__why"(v_integer, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- API keys: a signed-in user's own, or a principal's (a service's) made by someone holding
-- manage_keys on it; only a hash is kept
CREATE OR REPLACE FUNCTION authz.create_api_key(p_name text, p_scopes text DEFAULT '', p_expires_at timestamptz DEFAULT NULL,
  p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := 'ak_' || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
        v_scopes text[] := ARRAY(SELECT DISTINCT btrim(x) FROM unnest(string_to_array(coalesce(p_scopes, ''), ',')) x
                                 WHERE btrim(x) <> '' ORDER BY 1);
        v_cur text[] := authz_int.scopes_active(); v_bad text;
        v_type text := coalesce(p_principal_type, 'user'); v_id text;
BEGIN
  PERFORM authz_int.check_writable();
  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'name the key (its name says what it is for)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  PERFORM authz_int.key_owner_given(p_principal_type, p_principal_id);
  -- the principal's row is locked (FOR KEY SHARE) before it is checked: a delete of it waits for this key, or this
  -- for the delete, which leaves no principal to make it for (a delete with an older snapshot: keys_gone)
  IF p_principal_id IS NULL THEN
    PERFORM authz_int.users_only('authz.create_api_key for oneself');
    v_id := authz.uid()::text;
    IF v_type <> 'user' OR v_id IS NULL OR NOT authz_int.hold('user', v_id) THEN
      RAISE EXCEPTION 'sign in to create an API key' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714';
    END IF;
  ELSE
    v_id := authz_int.canon(v_type, p_principal_id);
    -- (no row there: authz.can holds only on rows that are, so the check refuses it, as one you can't manage)
    PERFORM authz_int.hold(v_type, v_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  SELECT string_agg(x, ', ') INTO v_bad FROM unnest(v_scopes) x
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'no scope % in the policy', v_bad USING HINT = 'rowstile help AZ707'; END IF;
  IF v_cur IS NOT NULL AND (cardinality(v_scopes) = 0 OR NOT v_scopes <@ v_cur) THEN
    RAISE EXCEPTION 'a key cannot have more scopes than the session creating it' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  INSERT INTO authz.api_keys (user_id, principal_type, name, prefix, hash, scopes, expires_at)
  VALUES (v_id, v_type, p_name, left(v_token, 10), encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
          array_to_string(v_scopes, ','), p_expires_at);
  PERFORM authz_int.mark_row(v_type, v_id);
  PERFORM authz_int.audit('create_api_key', v_type, v_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('name', p_name, 'scopes', v_scopes, 'expires_at', p_expires_at));
  RETURN v_token;
END $f$;

-- A principal's keys are named by its type and its id; a type without an id is a mistake, not one's own keys
CREATE FUNCTION authz_int.key_owner_given(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_id IS NULL AND coalesce(p_type, 'user') <> 'user' THEN
    RAISE EXCEPTION 'a key for % needs its id too (give neither for your own keys)', p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
END $f$;

-- Your keys, or (with manage_keys on it) a principal's
CREATE OR REPLACE FUNCTION authz.list_api_keys(p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS TABLE (id bigint, name text, prefix text, scopes text, created_at timestamptz, expires_at timestamptz,
               last_used_at timestamptz, revoked_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  PERFORM authz_int.key_owner_given(p_principal_type, p_principal_id);
  IF p_principal_id IS NULL THEN
    SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  ELSE
    v_type := coalesce(p_principal_type, 'user');
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  RETURN QUERY SELECT k.id, k.name, k.prefix, k.scopes, k.created_at, k.expires_at, k.last_used_at, k.revoked_at
  FROM authz.api_keys k WHERE k.user_id = v_id AND k.principal_type = v_type ORDER BY k.id;
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'team.member' THEN
      WITH want AS (SELECT DISTINCT x::integer AS m FROM unnest(p_members) x),
      del AS (DELETE FROM "app"."team_members" s WHERE s."team_id" = p_id::integer AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "app"."team_members" ("team_id", "user_id") SELECT p_id::integer, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "app"."team_members" s WHERE s."team_id" = p_id::integer AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, authz_int.canon(p_type, p_id), p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "conf_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."file__view", authz_int."file__viewer", authz_int."folder__edit", authz_int."folder__edit__direct", authz_int."folder__team", authz_int."folder__view", authz_int."folder__viewer" TO "conf_app";

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"conf_electric"'); v_app oid := to_regrole('"conf_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role conf_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE conf_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role conf_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role conf_electric and the app role conf_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role conf_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "conf_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "conf_electric";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__view"', 'authz_int."file__viewer"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."folder__team"', 'authz_int."folder__view"', 'authz_int."folder__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.files:column owner_id:items"', '"app.files:column owner_id:why"', '"app.files:insert:items"', '"app.files:insert:refuse"', '"app.files:insert:why"', '"app.files:rules:explain"', '"app.files:update:items"', '"app.files:update:refuse"', '"app.files:update:why"', '"app.folders:column parent_id after:items"', '"app.folders:column parent_id after:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.notes:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, integer, text)', 'authz.explain(text, integer, text, text)', 'authz.list_shares(text, integer)', 'authz.list_links(text, integer)', 'authz.revoke_link(text, integer, text)', 'authz.create_link(text, integer, text, timestamptz)', 'authz.create_role(text, integer, text, text, text[])', 'authz.roles_of(text, integer)', 'authz.request_access(text, integer, text, text, interval)', 'authz.break_glass(text, integer, text, text, interval)', 'authz.start_review(text, integer, timestamptz)', 'authz.can(text, integer, text)', 'authz.who_among(text, integer, text, text[], text)', 'authz.perms(text, integer)', 'authz.share(text, text, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, integer, text)', 'authz.share(text, integer, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, text, text)', 'authz.share(text, integer, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, integer, text)']::regprocedure[]))
UNION ALL
SELECT n.nspname::text, gw.who, a.privilege_type,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who)
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname = 'authz_sync' AND a.grantee <> n.nspowner
    AND NOT (a.grantee = to_regrole('"conf_electric"') AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON TABLE %s FROM %s CASCADE', a.privilege_type, c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND a.grantee <> c.relowner
    AND NOT (a.grantee = to_regrole('"conf_electric"') AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND att.attacl IS NOT NULL LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

